mapper.sql:
AND c.is_delete = 0 AND c.status = 'published'
AND (c.visibility = 'public' OR c.author_id = #{userId})
AND c.type = #{type}

mapper.select:
SELECT cc.content_id
FROM content_collect cc
         INNER JOIN content c ON cc.content_id = c.id
WHERE cc.user_id = #{userId}

ORDER BY cc.create_time DESC, cc.content_id DESC
    LIMIT #{offset}, #{size}
